<?php use App\Services\Publisher; $remoteLink=Publisher::remoteLink($record); ?>
<div class="page-heading"><div><div class="eyebrow">REVIEW &amp; PUBLISH</div><h1>Announcement review</h1><p>Review the saved version before sending it to WordPress.</p></div><span class="status-badge"><?= e(Publisher::status($record)) ?></span></div>
<?php if($record['publish_error']): ?><div class="alert alert-warning" role="alert"><?= e($record['publish_error']) ?></div><?php endif; ?>
<?php if($record['uncertain_stage'] || $record['status']==='publishing'): ?><div class="alert phase-alert">The last WordPress result may be incomplete. Retry checks the existing remote result before any new creation. Editing is blocked until it is reconciled.</div><?php endif; ?>
<div class="row g-4"><div class="col-lg-8"><article class="surface form-panel"><div class="preview-category"><?= e($mapping['category_name']) ?></div><h2 class="review-title"><?= e($record['title']) ?></h2><p class="preview-meta">PALECO · Revision <?= e($record['revision']) ?></p><?php if($record['type']==='partial'): ?><div class="preserve-lines"><?= e($record['body']) ?></div><?php else: ?><p class="small text-secondary">Interruption date: <?= e($record['interruption_date']) ?></p><?php require ROOT.'/app/Views/poster-images.php'; ?><?php endif; ?></article></div>
<div class="col-lg-4"><section class="surface form-panel"><h2>WordPress actions</h2><p class="small text-secondary">Category: <strong><?= e($mapping['category_name']) ?></strong><br>Remote post ID: <?= e($record['wordpress_post_id'] ?? 'Not created') ?></p>
<?php if($record['wordpress_post_id'] && (int)$record['synced_revision']!==(int)$record['revision']): ?><p class="small text-warning-emphasis">This saved version contains changes that have not been sent to WordPress.</p><?php endif; ?>
<?php if($record['wordpress_status']!=='publish'): ?><form method="post" action="<?= e(url('/publish')) ?>" class="mb-3" data-publishing-form><?= csrf() ?><input type="hidden" name="id" value="<?= e($record['id']) ?>"><input type="hidden" name="revision" value="<?= e($record['revision']) ?>"><input type="hidden" name="review_token" value="<?= e($reviewToken) ?>"><input type="hidden" name="action" value="draft"><button class="btn btn-outline-secondary w-100" type="submit"><?= $record['uncertain_stage']?'Retry / reconcile WordPress Draft':'Save as WordPress Draft' ?></button></form><?php endif; ?>
<button class="btn btn-navy w-100 mb-3" type="button" id="open-publish"><?= $record['wordpress_status']==='publish'?'Publish update to WordPress':'Publish to WordPress' ?></button>
<?php if(!$record['uncertain_stage'] && $record['status']!=='publishing'): ?><a class="btn btn-light w-100 mb-3" href="<?= e(url('/edit?id='.$record['id'])) ?>">Edit local announcement</a><?php endif; ?>
<?php if($remoteLink): ?><a class="btn btn-outline-secondary w-100 mb-3" href="<?= e($remoteLink) ?>" target="_blank" rel="noopener noreferrer"><?= $record['wordpress_status']==='publish'?'View on WordPress':'Open WordPress draft link' ?></a><?php if($record['wordpress_status']!=='publish'): ?><p class="small text-secondary">Draft previews may require WordPress sign-in.</p><?php endif; ?><?php endif; ?>
<a class="text-link" href="<?= e(url('/history')) ?>">← Back to publishing history</a><hr><p class="small text-secondary mb-0">WordPress Draft stays unpublished. Publish makes this advisory public. Repeated requests reuse the recorded post ID.</p></section></div></div>
<dialog id="publish-dialog" aria-labelledby="publish-dialog-title"><div class="form-panel"><h2 id="publish-dialog-title">Confirm public publication</h2><p class="text-secondary small">This action sends the saved announcement to the public WordPress website.</p><div class="preview-category"><?= e($mapping['category_name']) ?></div><h3><?= e($record['title']) ?></h3><div class="confirmation-preview"><?php if($record['type']==='partial'): ?><div class="preserve-lines"><?= e($record['body']) ?></div><?php else: ?><?php require ROOT.'/app/Views/poster-images.php'; ?><?php endif; ?></div>
<form method="post" action="<?= e(url('/publish')) ?>" data-publishing-form><?= csrf() ?><input type="hidden" name="id" value="<?= e($record['id']) ?>"><input type="hidden" name="revision" value="<?= e($record['revision']) ?>"><input type="hidden" name="review_token" value="<?= e($reviewToken) ?>"><input type="hidden" name="action" value="publish"><label class="form-check mt-3"><input class="form-check-input" type="checkbox" name="confirmed" value="1" required><span class="form-check-label">I confirm the title, category, and preview are correct and authorize public publication.</span></label><div class="form-actions"><button class="btn btn-navy" type="submit">Confirm and publish</button><button class="btn btn-light" type="button" id="cancel-publish">Cancel</button></div></form></div></dialog>
<h2 class="mt-4 mb-3">Publishing attempts</h2><div class="surface table-responsive"><table class="table"><thead><tr><th>Action</th><th>Acting user</th><th>Outcome</th><th>Result</th><th>Started (UTC)</th></tr></thead><tbody><?php foreach($attempts as $attempt): ?><tr><td><?= e($attempt['action']) ?> · v<?= e($attempt['revision']) ?></td><td><?= e($attempt['actor']) ?></td><td><?= e($attempt['outcome']) ?></td><td><?= e($attempt['message']) ?><?php if($attempt['wordpress_post_id']): ?><small class="d-block">Post ID <?= e($attempt['wordpress_post_id']) ?></small><?php endif; ?></td><td><?= e($attempt['started_at']) ?></td></tr><?php endforeach; ?><?php if(!$attempts): ?><tr><td colspan="5" class="p-4 text-secondary">No WordPress requests have been made for this announcement.</td></tr><?php endif; ?></tbody></table></div>
